package app.layan.quran;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;

/** Ten readers, two independent downloadable riwayat each. No new global preferences. */
public final class QiraatActivity extends LayanBaseActivity {
 public static final int READINGS_LIST=0x4c590201;private JSONObject catalog;private int group=-1;private ListView list;private BaseAdapter adapter;private TextView title;private boolean busy,closed;private final ExecutorService worker=Executors.newSingleThreadExecutor();private Future<?> task;private AtomicBoolean cancelled;private AlertDialog dialog;
 @Override protected void attachBaseContext(Context base){super.attachBaseContext(QiraatData.localized(base));}
 @Override public void onCreate(Bundle state){super.onCreate(state);frame(tr("القراءات العشر","Ten readings"),"");root.setLayoutDirection(ar()?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);LinearLayout header=(LinearLayout)root.getChildAt(0);header.getChildAt(0).setOnClickListener(v->onBackPressed());title=(TextView)((LinearLayout)header.getChildAt(1)).getChildAt(0);if(state!=null)group=state.getInt("group",-1);
  try{catalog=QiraatData.catalog(this);list=new ListView(this);list.setId(READINGS_LIST);list.setDivider(null);list.setPadding(dp(12),0,dp(12),0);adapter=new BaseAdapter(){public int getCount(){try{return group<0?catalog.getJSONArray("groups").length():2;}catch(Exception e){return 0;}}public Object getItem(int p){return p;}public long getItemId(int p){return p;}public View getView(int pos,View old,android.view.ViewGroup parent){LinearLayout wrap=column(),card=card();wrap.setPadding(0,dp(5),0,dp(5));try{if(group<0){JSONObject g=catalog.getJSONArray("groups").getJSONObject(pos);card.addView(label(g.getString(ar()?"nameArabic":"name"),24,ink));card.addView(label(tr("روايتان","Two riwayat"),14,muted));}else{String id=idAt(pos);JSONObject m=QiraatData.metadata(QiraatActivity.this,id);card.addView(label(m.getString(ar()?"nameArabic":"name"),23,ink));boolean ready=QiraatData.downloaded(QiraatActivity.this,id);String status=ready?tr("فتح · محمّلة","Open · Downloaded"):tr("تحميل ","Download ")+size(m.getLong("downloadBytes"));card.addView(label(status,16,green));if(!ready)card.addView(label(tr("المساحة بعد التحميل: ","Storage after download: ")+size(m.getLong("bytes")),13,muted));}LayanUi.navigation(card,group<0);((TextView)card.getChildAt(0)).setTypeface(android.graphics.Typeface.create("sans-serif",android.graphics.Typeface.BOLD));wrap.addView(card);}catch(Exception e){wrap.addView(label(tr("تعذّر عرض الرواية","Could not load riwayah"),18,ink));}return wrap;}};list.setAdapter(adapter);list.setOnItemClickListener((a,v,p,id)->{if(busy)return;if(group<0){group=p;refresh();}else try{openOrDownload(idAt(p));}catch(Exception e){toast(tr("تعذّر فتح الرواية","Could not open riwayah"));}});body.addView(list,new LinearLayout.LayoutParams(-1,-1));refresh();}catch(Exception e){body.addView(label(tr("تعذّر فتح القراءات","Could not open readings"),18,ink));}
 }
 private String idAt(int pos)throws Exception{return catalog.getJSONArray("groups").getJSONObject(group).getJSONArray("riwayat").getString(pos);}
 private void refresh(){try{title.setText(group<0?tr("القراءات العشر","Ten readings"):catalog.getJSONArray("groups").getJSONObject(group).getString(ar()?"nameArabic":"name"));}catch(Exception ignored){}if(adapter!=null)adapter.notifyDataSetChanged();}
 private void reader(String id){startActivity(new Intent(this,QiraatReaderActivity.class).putExtra("riwayah",id));}
 private void openOrDownload(String id){if(QiraatData.downloaded(this,id)){reader(id);return;}busy=true;cancelled=new AtomicBoolean();LinearLayout page=column();page.setPadding(dp(20),dp(15),dp(20),dp(15));TextView status=label(tr("جارٍ التحميل…","Downloading…"),18,ink);ProgressBar progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);page.addView(status);page.addView(progress,new LinearLayout.LayoutParams(-1,dp(22)));dialog=new LayanDialogBuilder(this).setTitle(tr("تحميل الرواية","Download riwayah")).setView(page).setNegativeButton(tr("إلغاء","Cancel"),(d,w)->cancelDownload()).create();dialog.setOnCancelListener(d->cancelDownload());dialog.show();AtomicBoolean token=cancelled;
  task=worker.submit(()->{try{final int[] last={-1};final boolean[] preparing={false};QiraatData.download(this,id,(percent,prep)->{if(token.get()||closed)throw new InterruptedIOException("Cancelled");if(prep&&!preparing[0]||!prep&&percent!=last[0]){preparing[0]=prep;last[0]=percent;runOnUiThread(()->{if(!closed&&dialog!=null){progress.setIndeterminate(prep);if(!prep)progress.setProgress(percent);status.setText(prep?tr("جارٍ تجهيز المصحف…","Preparing mushaf…"):tr("جارٍ التحميل… ","Downloading… ")+(ar()?digits(Integer.toString(percent)):percent)+"%");}});}});runOnUiThread(()->{if(closed)return;finishDownload();refresh();reader(id);});}catch(Exception e){android.util.Log.w("LayanQiraat","Riwayah download failed",e);runOnUiThread(()->{if(closed)return;finishDownload();refresh();toast(token.get()?tr("تم إلغاء التحميل","Download cancelled"):tr("تعذّر التحميل. تأكد من الإنترنت والمساحة المتاحة ثم حاول مجددًا.","Download failed. Check internet and free storage, then retry."));});}});
 }
 private void cancelDownload(){if(cancelled!=null)cancelled.set(true);if(task!=null)task.cancel(true);}
 private void finishDownload(){busy=false;if(dialog!=null){dialog.dismiss();dialog=null;}}
 @Override protected void onResume(){super.onResume();refresh();}
 @Override public void onBackPressed(){if(busy){cancelDownload();return;}if(group>=0){group=-1;refresh();}else super.onBackPressed();}
 @Override protected void onSaveInstanceState(Bundle state){state.putInt("group",group);super.onSaveInstanceState(state);}
 @Override protected void onDestroy(){closed=true;cancelDownload();if(dialog!=null)dialog.dismiss();worker.shutdownNow();super.onDestroy();}
 private boolean ar(){return getResources().getConfiguration().getLocales().get(0).getLanguage().equals("ar");}private String tr(String a,String e){return ar()?a:e;}
 private String size(long n){String value=String.format(Locale.US,"%.1f",n/1048576.0);return (ar()?digits(value):value)+tr(" ميجابايت"," MB");}
}
